import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import { dirname } from 'node:path';
import { randomBytes } from 'node:crypto';

// Books live in memory and every change is written back to a single JSON file.
export async function openStore(file) {
  let books = [];
  try {
    books = JSON.parse(await readFile(file, 'utf8'));
  } catch (err) {
    // A missing file just means no books yet. Anything else (e.g. a corrupt file)
    // should stop startup rather than risk overwriting the user's data.
    if (err.code !== 'ENOENT') throw err;
  }

  // Writes are queued so two quick changes can't interleave on disk, and each
  // write goes to a temp file first so a crash never leaves a half-written file.
  let queue = Promise.resolve();
  function save() {
    const data = JSON.stringify(books, null, 2) + '\n';
    const write = queue.catch(() => {}).then(async () => {
      await mkdir(dirname(file), { recursive: true });
      const tmp = `${file}.tmp`;
      await writeFile(tmp, data);
      await rename(tmp, file);
    });
    queue = write;
    return write;
  }

  function newId() {
    let id;
    do id = randomBytes(6).toString('base64url');
    while (books.some((b) => b.id === id));
    return id;
  }

  return {
    list() {
      return books;
    },

    get(id) {
      return books.find((b) => b.id === id) ?? null;
    },

    async add({ title, author = '', notes = '' }) {
      const book = {
        id: newId(),
        title,
        author,
        notes,
        status: 'reading',
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await save();
      return book;
    },

    async finish(id) {
      const book = this.get(id);
      if (!book) return null;
      if (book.status !== 'finished') {
        book.status = 'finished';
        book.finishedAt = new Date().toISOString();
        await save();
      }
      return book;
    },
  };
}

