const escapes = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

export function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, (c) => escapes[c]);
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  a { color: #1a5fb4; }
  h1 { margin-bottom: 0.25rem; }
  h2 { margin-top: 2rem; border-bottom: 1px solid #ddd; }
  ul { list-style: none; padding: 0; }
  li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: 0.5rem 0; border-bottom: 1px solid #f0f0f0; }
  .muted { color: #666; }
  .notes { white-space: pre-wrap; background: #fafafa; border-left: 3px solid #ddd; padding: 0.75rem 1rem; }
  .errors { color: #a51d2d; }
  form.add label { display: block; margin-top: 0.75rem; }
  form.add input, form.add textarea { width: 100%; box-sizing: border-box; font: inherit; padding: 0.4rem; }
  form.add textarea { min-height: 6rem; }
  button { font: inherit; padding: 0.3rem 0.8rem; cursor: pointer; }
  form.add button { margin-top: 1rem; }
</style>
</head>
<body>
${body}
</body>
</html>
`;
}

function byline(book) {
  return book.author ? ` <span class="muted">by ${escapeHtml(book.author)}</span>` : '';
}

function finishButton(book, from) {
  return `<form method="post" action="/books/${escapeHtml(book.id)}/finish">
    <input type="hidden" name="from" value="${from}">
    <button type="submit">Mark finished</button>
  </form>`;
}

export function homePage(books, { errors = [], values = {} } = {}) {
  const reading = books
    .filter((b) => b.status === 'reading')
    .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  const readingList = reading.length
    ? `<ul>${reading
        .map(
          (b) => `<li>
    <span><a href="/books/${escapeHtml(b.id)}">${escapeHtml(b.title)}</a>${byline(b)}</span>
    ${finishButton(b, 'home')}
  </li>`,
        )
        .join('\n')}</ul>`
    : '<p class="muted">Nothing on the go right now.</p>';

  const finishedList = finished.length
    ? `<ul>${finished
        .map(
          (b) => `<li>
    <span><a href="/books/${escapeHtml(b.id)}">${escapeHtml(b.title)}</a>${byline(b)}</span>
    <span class="muted">${formatDate(b.finishedAt)}</span>
  </li>`,
        )
        .join('\n')}</ul>`
    : '<p class="muted">No finished books yet.</p>';

  const errorList = errors.length
    ? `<ul class="errors">${errors.map((e) => `<li>${escapeHtml(e)}</li>`).join('')}</ul>`
    : '';

  return layout(
    'My books',
    `<h1>My books</h1>

<h2>Currently reading</h2>
${readingList}

<h2>Finished</h2>
${finishedList}

<h2>Add a book</h2>
${errorList}
<form class="add" method="post" action="/books">
  <label>Title <input name="title" required maxlength="300" value="${escapeHtml(values.title)}"></label>
  <label>Author <input name="author" maxlength="200" value="${escapeHtml(values.author)}"></label>
  <label>Notes <textarea name="notes" maxlength="10000">${escapeHtml(values.notes)}</textarea></label>
  <button type="submit">Add book</button>
</form>`,
  );
}

export function bookPage(book) {
  const status =
    book.status === 'finished'
      ? `<p class="muted">Finished ${formatDate(book.finishedAt)}</p>`
      : `<p class="muted">Currently reading</p>${finishButton(book, 'book')}`;

  const notes = book.notes
    ? `<div class="notes">${escapeHtml(book.notes)}</div>`
    : '<p class="muted">No notes.</p>';

  return layout(
    book.title,
    `<p><a href="/">&larr; All books</a></p>
<h1>${escapeHtml(book.title)}</h1>
${book.author ? `<p>by ${escapeHtml(book.author)}</p>` : ''}
${status}
<h2>Notes</h2>
${notes}`,
  );
}

export function notFoundPage() {
  return layout('Not found', `<h1>Not found</h1><p>There's no book here. <a href="/">Back to all books</a></p>`);
}

export function errorPage(message) {
  return layout('Error', `<h1>Something went wrong</h1><p>${escapeHtml(message)}</p><p><a href="/">Back to all books</a></p>`);
}

