import { homePage, bookPage, notFoundPage, errorPage } from './views.js';

const MAX_BODY_BYTES = 64 * 1024;
const LIMITS = { title: 300, author: 200, notes: 10000 };

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

function sendHtml(res, status, html) {
  res.writeHead(status, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Security-Policy': "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'",
    'X-Content-Type-Options': 'nosniff',
  });
  res.end(html);
}

function redirect(res, location) {
  // 303 so the browser follows up with a GET and a refresh won't resubmit the form.
  res.writeHead(303, { Location: location });
  res.end();
}

async function readForm(req) {
  const type = req.headers['content-type'] ?? '';
  if (!type.startsWith('application/x-www-form-urlencoded')) {
    throw new HttpError(415, 'Expected a form submission.');
  }
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw new HttpError(413, 'That submission is too large.');
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function validateBook(form) {
  const values = {
    title: (form.get('title') ?? '').trim(),
    author: (form.get('author') ?? '').trim(),
    notes: (form.get('notes') ?? '').trim(),
  };
  const errors = [];
  if (!values.title) errors.push('Please give the book a title.');
  for (const [field, max] of Object.entries(LIMITS)) {
    if (values[field].length > max) errors.push(`The ${field} can be at most ${max} characters.`);
  }
  return { values, errors };
}

export function createApp(store) {
  async function route(req, res) {
    const { pathname } = new URL(req.url, 'http://localhost');
    const method = req.method;

    if (pathname === '/') {
      if (method !== 'GET' && method !== 'HEAD') throw new HttpError(405, 'Method not allowed.');
      return sendHtml(res, 200, homePage(store.list()));
    }

    if (pathname === '/books') {
      if (method !== 'POST') throw new HttpError(405, 'Method not allowed.');
      const { values, errors } = validateBook(await readForm(req));
      if (errors.length) return sendHtml(res, 400, homePage(store.list(), { errors, values }));
      const book = await store.add(values);
      return redirect(res, `/books/${book.id}`);
    }

    let match = pathname.match(/^\/books\/([\w-]+)$/);
    if (match) {
      if (method !== 'GET' && method !== 'HEAD') throw new HttpError(405, 'Method not allowed.');
      const book = store.get(match[1]);
      if (!book) return sendHtml(res, 404, notFoundPage());
      return sendHtml(res, 200, bookPage(book));
    }

    match = pathname.match(/^\/books\/([\w-]+)\/finish$/);
    if (match) {
      if (method !== 'POST') throw new HttpError(405, 'Method not allowed.');
      const form = await readForm(req);
      const book = await store.finish(match[1]);
      if (!book) return sendHtml(res, 404, notFoundPage());
      return redirect(res, form.get('from') === 'home' ? '/' : `/books/${book.id}`);
    }

    return sendHtml(res, 404, notFoundPage());
  }

  return async function handler(req, res) {
    try {
      await route(req, res);
    } catch (err) {
      if (err instanceof HttpError) {
        sendHtml(res, err.status, errorPage(err.message));
      } else {
        console.error(err);
        sendHtml(res, 500, errorPage('Sorry, that did not work. Please try again.'));
      }
    }
  };
}

