import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { createServer } from 'node:http';
import { mkdtemp, rm, readFile, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { openStore } from '../src/store.js';
import { createApp } from '../src/app.js';

let dir, file, server, base;

async function start() {
  const store = await openStore(file);
  server = createServer(createApp(store));
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  base = `http://127.0.0.1:${server.address().port}`;
}

async function stop() {
  await new Promise((r) => server.close(r));
}

function post(path, fields) {
  return fetch(base + path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });
}

async function addBook(fields) {
  const res = await post('/books', fields);
  expect(res.status).toBe(303);
  return res.headers.get('location');
}

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  file = join(dir, 'books.json');
  await start();
});

afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe('books app', () => {
  it('shows empty sections and the add form on first open', async () => {
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Nothing on the go right now.');
    expect(html).toContain('No finished books yet.');
    expect(html).toContain('<form class="add" method="post" action="/books">');
  });

  it('adds a book and shows its own page with title, author and notes', async () => {
    const location = await addBook({ title: 'Middlemarch', author: 'George Eliot', notes: 'Slow start.\nWorth it.' });
    expect(location).toMatch(/^\/books\/[\w-]+$/);

    const page = await fetch(base + location);
    expect(page.status).toBe(200);
    const html = await page.text();
    expect(html).toContain('<h1>Middlemarch</h1>');
    expect(html).toContain('by George Eliot');
    expect(html).toContain('Slow start.\nWorth it.');
    expect(html).toContain('Currently reading');

    const home = await (await fetch(base + '/')).text();
    expect(home).toContain(`<a href="${location}">Middlemarch</a>`);
  });

  it('marks a book as finished and moves it to the finished section', async () => {
    const location = await addBook({ title: 'Dune', author: 'Frank Herbert' });

    const res = await post(`${location}/finish`, { from: 'home' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const home = await (await fetch(base + '/')).text();
    const [reading, finished] = home.split('<h2>Finished</h2>');
    expect(reading).not.toContain('Dune');
    expect(finished.split('<h2>Add a book</h2>')[0]).toContain('Dune');

    const page = await (await fetch(base + location)).text();
    expect(page).toContain('Finished ');
    expect(page).not.toContain('Mark finished');
  });

  it('redirects back to the book page when finished from there', async () => {
    const location = await addBook({ title: 'Emma' });
    const res = await post(`${location}/finish`, { from: 'book' });
    expect(res.headers.get('location')).toBe(location);
  });

  it('keeps books after a restart', async () => {
    const location = await addBook({ title: 'Persuasion', author: 'Jane Austen', notes: 'Re-read' });
    await post(`${location}/finish`, {});
    await stop();
    await start();

    const html = await (await fetch(base + location)).text();
    expect(html).toContain('<h1>Persuasion</h1>');
    expect(html).toContain('Re-read');
    expect(html).toContain('Finished ');

    const saved = JSON.parse(await readFile(file, 'utf8'));
    expect(saved).toHaveLength(1);
    expect(saved[0]).toMatchObject({ title: 'Persuasion', status: 'finished' });
  });

  it('rejects a book without a title and keeps what was typed', async () => {
    const res = await post('/books', { title: '  ', author: 'Anon', notes: 'hello' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Please give the book a title.');
    expect(html).toContain('value="Anon"');
    expect(html).toContain('>hello</textarea>');
  });

  it('escapes user input in the pages', async () => {
    const location = await addBook({ title: '<script>alert(1)</script>', author: '"Quote"', notes: '<b>x</b>' });
    const html = await (await fetch(base + location)).text();
    expect(html).not.toContain('<script>alert(1)</script>');
    expect(html).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
    expect(html).toContain('&lt;b&gt;x&lt;/b&gt;');
  });

  it('returns 404 for unknown books', async () => {
    expect((await fetch(base + '/books/nope')).status).toBe(404);
    expect((await post('/books/nope/finish', {})).status).toBe(404);
    expect((await fetch(base + '/elsewhere')).status).toBe(404);
  });

  it('refuses to start over a corrupt data file rather than wiping it', async () => {
    await writeFile(file, '{ not json');
    await expect(openStore(file)).rejects.toThrow();
    expect(await readFile(file, 'utf8')).toBe('{ not json');
  });
});

